import json

# Look through the JSON for all table descriptions
for year in [1972]:
    filename = f'/app/resources/treasury_bulletin_{year}_04.json'
    with open(filename, 'r') as f:
        data = json.load(f)

    elements = data.get('document', {}).get('elements', [])

    table_descs = set()
    for i, elem in enumerate(elements):
        if not elem:
            continue
        if elem.get('type') == 'table':
            desc = elem.get('description', '') or ''
            if desc:
                table_descs.add(desc[:80])

    print("Tables with descriptions:")
    for desc in sorted(table_descs):
        print(f"  {desc}")
